def calc_conf(base, mods, deps, param_imp=True, domain_lim=False, ind_gap=False):
    c = base + sum(mods)
    for dep in deps:
        if dep < 0.95:
            c *= dep
    if param_imp:
        c *= 0.70
    if domain_lim:
        c *= 0.60
    if ind_gap:
        c *= 0.80
    return c

